def decode(data: bytes) -> Frame

class RingBuffer {
  def __init__(self, capacity)
  def __len__(self)
  @property def capacity(self)
  /** Appends an item, overwriting the oldest one when the buffer is full. */
  def push(self, item)
  /** Returns all items oldest first and empties the buffer. */
  def drain(self)
}

/** Keeps every n-th reading per vehicle. */
class Sampler {
  def __init__(self, every=1)
  def accept(self, frame: Frame) -> bool
  def reset(self)
}

